import { createHash, createPrivateKey, createPublicKey, generateKeyPairSync, randomBytes, sign, X509Certificate, type KeyObject } from "node:crypto";
import { chmod, mkdir, readFile, rename, writeFile } from "node:fs/promises";
import { homedir } from "node:os";
import { join } from "node:path";

/**
 * The local CA the usage proxy signs its one intercepted host with. Generated by AIS on first use, kept at
 * `~/.ais/gateway-local-ca/` (`ca.pem` public, `ca-key.pem` 0600). Clients trust it only through NODE_EXTRA_CA_CERTS:
 * the system trust store is never touched. The CA carries a critical name constraint, so even its key can only ever
 * mint certificates for the intercepted hosts.
 */
export const defaultCaDir = (): string => process.env.AIS_GATEWAY_LOCAL_CA_DIR || join(homedir(), ".ais", "gateway-local-ca");
export const caCertPath = (dir = defaultCaDir()): string => join(dir, "ca.pem");
const caKeyPath = (dir: string): string => join(dir, "ca-key.pem");

const CA_DAYS = 3650;
const LEAF_DAYS = 365;

// --- minimal DER writer -------------------------------------------------------------------------------------------

function len(n: number): Buffer {
  if (n < 0x80) return Buffer.from([n]);
  const bytes: number[] = [];
  for (let v = n; v > 0; v = Math.floor(v / 256)) bytes.unshift(v & 0xff);
  return Buffer.from([0x80 | bytes.length, ...bytes]);
}
const tlv = (tag: number, ...parts: Buffer[]): Buffer => {
  const body = Buffer.concat(parts);
  return Buffer.concat([Buffer.from([tag]), len(body.length), body]);
};
const seq = (...parts: Buffer[]): Buffer => tlv(0x30, ...parts);
const set = (...parts: Buffer[]): Buffer => tlv(0x31, ...parts);
const octets = (b: Buffer): Buffer => tlv(0x04, b);
const bits = (b: Buffer): Buffer => tlv(0x03, Buffer.from([0]), b);
const bool = (v: boolean): Buffer => tlv(0x01, Buffer.from([v ? 0xff : 0]));
const utf8 = (s: string): Buffer => tlv(0x0c, Buffer.from(s, "utf8"));
const int = (b: Buffer): Buffer => tlv(0x02, (b[0] ?? 0) & 0x80 ? Buffer.concat([Buffer.from([0]), b]) : b);

/** An OBJECT IDENTIFIER from its arcs (kept as arrays: dotted strings read like addresses to the privacy scan). */
function oid(arcs: number[]): Buffer {
  const [a, b, ...rest] = arcs as [number, number, ...number[]];
  const out = [a * 40 + b];
  for (const n of rest) {
    const chunk = [n & 0x7f];
    for (let v = Math.floor(n / 128); v > 0; v = Math.floor(v / 128)) chunk.unshift(0x80 | (v & 0x7f));
    out.push(...chunk);
  }
  return tlv(0x06, Buffer.from(out));
}

function time(d: Date): Buffer {
  const iso = d.toISOString().replace(/[-:T]/g, "").slice(0, 14) + "Z"; // YYYYMMDDHHMMSSZ
  return d.getUTCFullYear() < 2050 ? tlv(0x17, Buffer.from(iso.slice(2))) : tlv(0x18, Buffer.from(iso));
}

const name = (cn: string): Buffer => seq(set(seq(oid([2, 5, 4, 3]), utf8(cn))));
const ext = (id: number[], critical: boolean, value: Buffer): Buffer => seq(oid(id), ...(critical ? [bool(true)] : []), octets(value));
const dnsName = (host: string): Buffer => tlv(0x82, Buffer.from(host, "ascii"));
const ECDSA_SHA256 = seq(oid([1, 2, 840, 10045, 4, 3, 2]));

/** SHA-1 of the subjectPublicKey bits: the usual key identifier. */
function keyId(pub: KeyObject): Buffer {
  const spki = pub.export({ type: "spki", format: "der" });
  // EC P-256 SPKI: the key bits are the last 65 bytes.
  return createHash("sha1").update(spki.subarray(spki.length - 65)).digest();
}

interface CertSpec {
  subject: string;
  issuer: string;
  subjectKey: KeyObject;
  issuerKey: KeyObject;
  issuerKeyId: Buffer;
  days: number;
  now: Date;
  extensions: Buffer[];
}

function buildCert(spec: CertSpec): string {
  const serial = randomBytes(16);
  serial[0] = (serial[0]! & 0x7f) | 0x01;
  const notBefore = new Date(spec.now.getTime() - 60 * 60_000);
  const notAfter = new Date(spec.now.getTime() + spec.days * 86_400_000);
  const spki = spec.subjectKey.export({ type: "spki", format: "der" });
  const tbs = seq(
    tlv(0xa0, int(Buffer.from([2]))),
    int(serial),
    ECDSA_SHA256,
    name(spec.issuer),
    seq(time(notBefore), time(notAfter)),
    name(spec.subject),
    spki,
    tlv(0xa3, seq(...spec.extensions, ext([2, 5, 29, 14], false, octets(keyId(spec.subjectKey))), ext([2, 5, 29, 35], false, seq(tlv(0x80, spec.issuerKeyId))))),
  );
  const sig = sign("sha256", tbs, { key: spec.issuerKey, dsaEncoding: "der" });
  const der = seq(tbs, ECDSA_SHA256, bits(sig));
  return `-----BEGIN CERTIFICATE-----\n${der.toString("base64").replace(/.{1,64}/g, "$&\n")}-----END CERTIFICATE-----\n`;
}

// --- CA and leaf ----------------------------------------------------------------------------------------------------

export interface LocalCa {
  certPem: string;
  key: KeyObject;
  /** Path of the public certificate (what NODE_EXTRA_CA_CERTS points at). */
  certPath: string;
}

/** The hosts the CA may ever sign for (its critical name constraint). */
export const CA_PERMITTED_HOSTS = ["api.anthropic.com"];

function newCa(now: Date): { certPem: string; keyPem: string } {
  const { privateKey, publicKey } = generateKeyPairSync("ec", { namedCurve: "P-256" });
  const id = keyId(publicKey);
  const certPem = buildCert({
    subject: "AIS gateway local CA",
    issuer: "AIS gateway local CA",
    subjectKey: publicKey,
    issuerKey: privateKey,
    issuerKeyId: id,
    days: CA_DAYS,
    now,
    extensions: [
      ext([2, 5, 29, 19], true, seq(bool(true), int(Buffer.from([0])))), // CA, pathlen 0
      ext([2, 5, 29, 15], true, tlv(0x03, Buffer.from([0x01, 0x06]))), // keyCertSign, cRLSign
      ext([2, 5, 29, 30], true, seq(tlv(0xa0, ...CA_PERMITTED_HOSTS.map((h) => seq(dnsName(h)))))), // name constraints
    ],
  });
  return { certPem, keyPem: privateKey.export({ type: "pkcs8", format: "pem" }) as string };
}

/** Loads the CA from `dir`, creating it (key 0600, directory 0700) when absent, unreadable or expired. */
export async function ensureLocalCa(dir = defaultCaDir(), now = new Date()): Promise<LocalCa> {
  const certPath = caCertPath(dir);
  const keyPath = caKeyPath(dir);
  try {
    const [certPem, keyPem] = await Promise.all([readFile(certPath, "utf8"), readFile(keyPath, "utf8")]);
    const cert = new X509Certificate(certPem);
    const key = createPrivateKey(keyPem);
    // Keep a CA with at least 30 days left whose key matches; otherwise make a new one.
    if (cert.checkPrivateKey(key) && Date.parse(cert.validTo) > now.getTime() + 30 * 86_400_000) {
      await chmod(keyPath, 0o600);
      return { certPem, key, certPath };
    }
  } catch {
    // absent or unreadable: generate below
  }
  await mkdir(dir, { recursive: true, mode: 0o700 });
  await chmod(dir, 0o700);
  const fresh = newCa(now);
  // Key first, each written to a temp file and renamed, so a reader never sees a cert without its key.
  await writeFile(`${keyPath}.tmp`, fresh.keyPem, { mode: 0o600 });
  await chmod(`${keyPath}.tmp`, 0o600);
  await rename(`${keyPath}.tmp`, keyPath);
  await writeFile(`${certPath}.tmp`, fresh.certPem, { mode: 0o644 });
  await rename(`${certPath}.tmp`, certPath);
  return { certPem: fresh.certPem, key: createPrivateKey(fresh.keyPem), certPath };
}

/** A server certificate for `host` signed by the CA. The leaf key lives in memory only. */
export function issueLeaf(ca: LocalCa, host: string, now = new Date()): { certPem: string; keyPem: string } {
  const { privateKey, publicKey } = generateKeyPairSync("ec", { namedCurve: "P-256" });
  const caCert = new X509Certificate(ca.certPem);
  const certPem = buildCert({
    subject: host,
    issuer: caCert.subject.replace(/^CN=/, ""),
    subjectKey: publicKey,
    issuerKey: ca.key,
    issuerKeyId: keyId(createPublicKey(ca.key.export({ type: "pkcs8", format: "pem" }))),
    days: LEAF_DAYS,
    now,
    extensions: [
      ext([2, 5, 29, 19], true, seq()),
      ext([2, 5, 29, 15], true, tlv(0x03, Buffer.from([0x07, 0x80]))), // digitalSignature
      ext([2, 5, 29, 37], false, seq(oid([1, 3, 6, 1, 5, 5, 7, 3, 1]))), // serverAuth
      ext([2, 5, 29, 17], false, seq(dnsName(host))),
    ],
  });
  return { certPem, keyPem: privateKey.export({ type: "pkcs8", format: "pem" }) as string };
}
